import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        // Walk from the longest: pair neighbours that differ by at most 1, else drop the longer one.
        long[] pairs = new long[n / 2 + 1];
        int k = 0;
        for (int i = n - 1; i >= 1;) {
            if (a[i] - a[i - 1] <= 1) {
                pairs[k++] = a[i - 1];
                i -= 2;
            } else i--;
        }
        // The two largest sides form a rectangle, then the next two, and so on.
        long answer = 0;
        for (int i = 0; i + 1 < k; i += 2) answer += pairs[i] * pairs[i + 1];
        System.out.println(answer % 1000000007);
    }
}

